using System.Globalization;
using System.Text.Json;
using Metarill.Core.Metadata;
using Xunit;
namespace Metarill.Generation.Tests;

/// <summary>全局下拉、单选与普通项目下拉共存，仍由元数据生成原页面。</summary>
[Collection(StandaloneProcessBudgetCollection.Name)]
public sealed class GlobalSingleFreshCatalogTests
{
    /// <summary>字符串／整数下拉、目标项目列及来源父范围的交叉模型实际打包，并运行包内原Vue。</summary>
    [Theory][InlineData("cross3")][InlineData("cross5")][InlineData("cross6")][InlineData("cross7")]
    public async Task Global_single_controls_package_and_keep_original_interactions(string profile)
    {
        var c=Catalog(profile);var before=JsonSerializer.Serialize(c);var boundary=Path.Combine(Path.GetTempPath(),"metarill-global-single-catalog");var directory=Path.Combine(boundary,Guid.NewGuid().ToString("N"));try{var output=Path.Combine(directory,"application");var model=GenerationModel.Create(c,"Example.GlobalSingleFresh");Assert.Empty(GenerationCapabilityAudit.Collect(model));Assert.True(new ApplicationPackager().Create(c,output,model.Namespace,NonRedundantApplicationFixture.Root()).FrontendIncluded);var probe=NonRedundantApplicationFixture.Start("node",output);foreach(var argument in new[]{Path.Combine(NonRedundantApplicationFixture.TestDirectory(),"GlobalSingleVueProbe.mjs"),output,Definition(profile).NameField})probe.ArgumentList.Add(argument);await NonRedundantApplicationFixture.RunAsync(probe);Assert.Equal(before,JsonSerializer.Serialize(c));foreach(var path in new[]{"components/yzp-relation-select/yzp-relation-select.vue","common/yzp_runtime/originalSelectionPageMixin.js"})Assert.Equal(File.ReadAllBytes(Path.Combine(NonRedundantApplicationFixture.Root(),"frontend/metarill_uni_admin",path)),File.ReadAllBytes(Path.Combine(output,"frontend",path)));}finally{if(Directory.Exists(directory))await TestDirectoryCleanup.DeleteAsync(directory,boundary);}
    }
    /// <summary>隐藏字段、页覆盖与全局缓存不能跳过单值完整用途证明。</summary>
    [Theory][InlineData("targetR0")][InlineData("variable")][InlineData("unpublished")][InlineData("conflictPage")][InlineData("hiddenBad")][InlineData("nameOverride")][InlineData("cachedName")][InlineData("credentialOutput")][InlineData("type2")]
    public async Task Unproven_global_single_controls_reject_before_staging(string kind)
    {
        var c=Catalog("cross3");if(kind=="targetR0")c.ConfigTables.Single(x=>x.Id=="3").IsRongyu=0;if(kind=="variable")c.ConfigPages.Single(x=>x.Id=="301").WhereSql="yz_project_id=@current_yz_project_id AND status=1";if(kind=="unpublished")c.ConfigTables.Single(x=>x.Id=="3").YzProjectId="";if(kind=="conflictPage")c.ConfigColumns.Single(x=>x.Id=="2190").Extra["linkConfigPageId"]=JsonSerializer.SerializeToElement("401");if(kind=="hiddenBad")c.ConfigColumns.Single(x=>x.Id=="2198").ControlDetail="{\"tableId\":\"3\",\"pageId\":\"missing\",\"nameField\":\"name\"}";if(kind=="nameOverride")c.ConfigPageColumns.Single(x=>x.ConfigColumnId=="2190").Extra["controlDetail"]=JsonSerializer.SerializeToElement("{\"nameField\":\"score\"}");if(kind=="cachedName")c.ConfigColumns.Single(x=>x.ConfigTableId=="3"&&x.ColumnName=="name").Extra["isJoinColumn"]=JsonSerializer.SerializeToElement(1);if(kind=="credentialOutput"){c.ConfigColumns.Add(new(){Id="3199",ConfigTableId="3",YzProjectId=c.YzProjectId,ColumnName="password",LogicalType="string"});c.ConfigColumns.Single(x=>x.Id=="2194").Extra["columnFullName"]=JsonSerializer.SerializeToElement("shared.password");}if(kind=="type2")c.ConfigPages.Single(x=>x.Id=="303").Extra["type"]=JsonSerializer.SerializeToElement(2);
        var boundary=Path.Combine(Path.GetTempPath(),"metarill-global-single-reject");var output=Path.Combine(boundary,Guid.NewGuid().ToString("N"));try{Assert.ThrowsAny<Exception>(()=>new ApplicationPackager().Create(c,output,"Example.InvalidGlobalSingle",NonRedundantApplicationFixture.Root()));Assert.False(Directory.Exists(output));}finally{if(Directory.Exists(output))await TestDirectoryCleanup.DeleteAsync(output,boundary);}
    }
    /// <summary>每个形态固定于发布模型，不由请求提供表或范围。</summary>
    internal static (string Type,bool NoProject,bool Parent,string NameField) Definition(string profile)=>profile switch
    {
        "cross3"=>("string",false,false,"name"),"cross5"=>("int64",true,true,"caption"),"cross6"=>("int64",false,false,"name"),"cross7"=>("string",true,true,"caption"),_=>throw new ArgumentOutOfRangeException(nameof(profile))
    };
    /// <summary>全局只用于目标；来源、来源父及普通候选始终有项目范围，隐藏默认不进入原VO。</summary>
    internal static MetadataCatalog Catalog(string profile)
    {
        const long first=9007199254745001;var d=Definition(profile);var c=new MetadataCatalog{YzProjectId="9007199254740993",YzProjectName="全局单值正式验收",YzAdminTypes=[new(){Id="5",YzProjectId="9007199254740993"}]};
        foreach(var(id,name,mode)in new[]{("2","source",0),("3","shared",1),("4","tenant",1),("5","parent",1)})
        {
            c.ConfigTables.Add(new(){Id=id,YzProjectId=c.YzProjectId,TableName="gs_single_"+name,IsRongyu=mode});var stem=(int.Parse(id,CultureInfo.InvariantCulture)*1000+100).ToString(CultureInfo.InvariantCulture);Add(stem+"1",id,"id","ID","int64",key:true);Add(stem+"2",id,id=="3"?d.NameField:"name",id=="3"?"共享名称":"记录名","string");if(id!="3"||!d.NoProject)Add(stem+"3",id,"yz_project_id","项目","int64");Add(stem+"4",id,"delete_no","删除标记","datetime");if(id is "3" or "4"){Add(stem+"5",id,"status","状态","int32");Add(stem+"6",id,"segment","分组","int32");}if(id=="3")Add(stem+"7",id,"score","分值","decimal");
            var page=id+"01";c.ConfigPages.Add(new(){Id=page,YzProjectId=c.YzProjectId,YzAdminTypeId="5",ConfigTableId=id,IsCopy=id=="2"?1:0,IsImport=id=="2"?1:0,IsExport=id=="2"?1:0,WhereSql=id=="3"?"status=1":"yz_project_id=@current_yz_project_id"+(id=="4"?" AND status=1":"")});foreach(var column in c.ConfigColumns.Where(x=>x.ConfigTableId==id&&!new[]{"id","yz_project_id","delete_no"}.Contains(x.ColumnName)))Field(page,column.Id,column.ColumnName!="score");
        }
        c.ConfigTables.Single(x=>x.Id=="3").Extra["scopeKind"]=JsonSerializer.SerializeToElement("global");c.ConfigPages.Add(new(){Id="303",YzProjectId=c.YzProjectId,YzAdminTypeId="5",ConfigTableId="3",WhereSql="status=1 AND segment=1",Extra=new(){["type"]=JsonSerializer.SerializeToElement(1)}});foreach(var field in c.ConfigPageColumns.Where(x=>x.ConfigPageId=="301").ToArray()){var copy=JsonSerializer.Deserialize<PageColumnMetadata>(JsonSerializer.Serialize(field))!;copy.Id="303"+field.Id;copy.ConfigPageId="303";c.ConfigPageColumns.Add(copy);}
        Add("2190","2","shared_id","共享下拉",d.Type);Relation("2190","List","3","301",d.NameField,"segment=@formParameters.segment");Add("2191","2","selected_id","共享单选","int64");Relation("2191","SelectPage","3","303",d.NameField,"");Add("2192","2","tenant_id","项目下拉","int64");Relation("2192","List","4","401","name","");Add("2193","2","parent_id","来源父","int64");c.ConfigColumns.Single(x=>x.Id=="2193").LinkConfigTableId="5";if(d.Parent)c.ConfigPages.Single(x=>x.Id=="201").WhereSql+=" AND parent_id=@parent_id";
        Add("2106","2","segment","分组","int32");c.ConfigColumns.Single(x=>x.Id=="2106").DefaultValue="1";Field("201","2106",true);Add("2194","2","shared_score","共享分值","decimal");Join("2194","shared.score");Add("2195","2","selected_"+d.NameField,"单选名称","string");Join("2195","selected."+d.NameField);Add("2197","2","shared_"+d.NameField,"下拉名称","string");Join("2197","shared."+d.NameField);Add("2198","2","hidden_id","隐藏默认","int64");Relation("2198","List","3","301",d.NameField,"");c.ConfigColumns.Single(x=>x.Id=="2198").DefaultValue=first.ToString(CultureInfo.InvariantCulture);c.ConfigPageColumns.RemoveAll(x=>x.ConfigColumnId=="2198");
        // 普通R0中间节点的名称继续联到共享物理终点，验证真实的两跳派生候选与显示。
        c.ConfigTables.Add(new(){Id="6",YzProjectId=c.YzProjectId,TableName="gs_single_middle",IsRongyu=0});Add("6101","6","id","ID","int64",key:true);Add("6102","6","yz_project_id","项目","int64");Add("6103","6","delete_no","删除标记","datetime");Add("6104","6","shared_id","共享记录","int64");var middleForeign=c.ConfigColumns.Single(x=>x.Id=="6104");middleForeign.LinkConfigTableId="3";middleForeign.ControlKind="List";middleForeign.Extra["linkConfigPageId"]=JsonSerializer.SerializeToElement("301");middleForeign.ControlDetail=JsonSerializer.Serialize(new{tableId="3",table="gs_single_shared",pageId="301",nameField=d.NameField});Add("6105","6","label","派生名称","string");c.ConfigColumns.Single(x=>x.Id=="6105").Extra=new(){["isJoinColumn"]=JsonSerializer.SerializeToElement(1),["columnFullName"]=JsonSerializer.SerializeToElement("shared."+d.NameField)};c.ConfigPages.Add(new(){Id="601",ConfigTableId="6",YzProjectId=c.YzProjectId,YzAdminTypeId="5",WhereSql="yz_project_id=@current_yz_project_id"});Field("601","6104",true);Field("601","6105",false);Add("2200","2","nested_id","嵌套下拉","int64");var nested=c.ConfigColumns.Single(x=>x.Id=="2200");nested.LinkConfigTableId="6";nested.ControlKind="List";nested.ControlDetail="{\"tableId\":\"6\",\"table\":\"gs_single_middle\",\"nameField\":\"label\"}";Field("201","2200",true);Add("2201","2","nested_label","嵌套名称","string");Join("2201","nested.label");
        Add("9001","2","attachments","附件","string");var file=c.ConfigColumns.Single(x=>x.Id=="9001");file.ColumnLength="max";file.ControlKind="FileLibrary";file.ControlDetail="{\"accessMode\":\"PROTECTED\",\"maxCount\":3}";Field("201","9001",true);foreach(var page in c.ConfigPages)c.ConfigMenus.Add(new(){Id="700"+page.Id,YzProjectId=c.YzProjectId,YzAdminTypeId="5",Name="全局单值"+page.Id,Kind="GENERATED_PAGE",ConfigPageId=page.Id});return c;
        /// <summary>只构造验收元数据，实体、Mapper及CRUD全部由生成器提供。</summary>
        void Add(string id,string table,string name,string label,string type,bool key=false)=>c.ConfigColumns.Add(new(){Id=id,YzProjectId=c.YzProjectId,ConfigTableId=table,ColumnName=name,Name=label,LogicalType=type,IsDbNotNull=key?1:0,ColumnLength=type=="string"?"100":""});
        /// <summary>可读与可写仍使用原页面字段开关。</summary>
        void Field(string page,string id,bool edit)=>c.ConfigPageColumns.Add(new(){Id=page+id,YzProjectId=c.YzProjectId,ConfigPageId=page,ConfigColumnId=id,IsEdit=edit?1:0,IsShow=1});
        /// <summary>弹层页与显示页写入同一明确声明，避免读写各挑一个目标。</summary>
        void Relation(string id,string kind,string table,string page,string name,string where){var column=c.ConfigColumns.Single(x=>x.Id==id);column.ControlKind=kind;column.LinkConfigTableId=table;column.Extra["linkConfigPageId"]=JsonSerializer.SerializeToElement(page);column.ControlDetail=JsonSerializer.Serialize(new{tableId=table,table="gs_single_"+(table=="3"?"shared":"tenant"),pageId=page,nameField=name,whereSql=where,buttonText="选择记录"});Field("201",id,true);}
        /// <summary>联接值只读，原名称筛选键仍可搜索。</summary>
        void Join(string id,string path){var column=c.ConfigColumns.Single(x=>x.Id==id);column.Extra["isJoinColumn"]=JsonSerializer.SerializeToElement(1);column.Extra["columnFullName"]=JsonSerializer.SerializeToElement(path);Field("201",id,false);if(id is "2195" or "2197")c.ConfigPageColumns.Single(x=>x.ConfigColumnId==id).Extra["isSearch"]=JsonSerializer.SerializeToElement(1);}
    }
}
